<?php declare(strict_types=1); $base=config('app.base_path'); $esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $statuses=['PENDING','ACCEPTED','PREPARING','READY','ASSIGNED','OUT_FOR_DELIVERY','DELIVERED','COMPLETED','CANCELLED','REJECTED']; ?>
<div class="page-header"><div><h1>Restaurant Orders</h1><p>Receive, process and complete restaurant customer orders.</p></div><div class="page-actions"><a class="btn btn-primary" href="<?= $base ?>/restaurant/orders/create-test">Create Test Customer Order</a></div></div>
<div class="card"><form method="get" class="order-filters"><label>Restaurant<select name="restaurant_id"><option value="0">All Restaurants</option><?php foreach($restaurants as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $selected_restaurant_id==(int)$r['id']?'selected':'' ?>><?= $esc($r['name']) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $s): ?><option value="<?= $s ?>" <?= $selected_status===$s?'selected':'' ?>><?= str_replace('_',' ',$s) ?></option><?php endforeach; ?></select></label><button class="btn btn-secondary" type="submit">Filter</button></form></div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Restaurant</th><th>Customer</th><th>Type</th><th>Status</th><th>Total</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= $esc($o['order_no']) ?></strong></td><td><?= $esc($o['restaurant_name']) ?></td><td><?= $esc(trim((string)$o['member_name'])) ?><br><small><?= $esc($o['customer_phone']) ?></small></td><td><?= $esc($o['order_type']) ?></td><td><span class="order-status <?= strtolower($esc($o['status'])) ?>"><?= str_replace('_',' ',$esc($o['status'])) ?></span></td><td>₹<?= number_format((float)$o['total'],2) ?></td><td><?= $esc($o['created_at']) ?></td><td><a class="link-button" href="<?= $base ?>/restaurant/orders/<?= (int)$o['id'] ?>">View</a></td></tr><?php endforeach; if(!$orders): ?><tr><td colspan="8"><div class="empty-state">No restaurant orders found.</div></td></tr><?php endif; ?></tbody></table></div></div>
<style>.order-filters{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.order-filters label{display:grid;gap:6px;font-weight:700;font-size:13px}.order-filters select{min-width:240px;padding:9px}.order-status{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef2ff;font-size:11px;font-weight:800}.order-status.pending{background:#fff7ed}.order-status.accepted,.order-status.preparing,.order-status.ready{background:#ecfdf5}.order-status.cancelled,.order-status.rejected{background:#fef2f2}.order-status.completed,.order-status.delivered{background:#eff6ff}</style>
